import{_ as n,o as r,c as i,a3 as t}from"./chunks/framework.z_KJ15Ep.js";const s="/bilder/grundlagen/einfuehrung-reports-beispiel-klassenliste.png",a="/bilder/grundlagen/einfuehrung-reports-beispiel-lehrerliste.png",l="/bilder/grundlagen/einfuehrung-reports-beispiel-stammblatt.png",u="/bilder/grundlagen/einfuehrung-report-zeugnisse.png",f=JSON.parse('{"title":"Reports und ihre Einsatzmöglichkeiten verstehen","description":"","frontmatter":{"title":"Reports und ihre Einsatzmöglichkeiten verstehen","source_pageid":1271,"source_revision":4665},"headers":[],"relativePath":"einstieg/grundlagen/was-ist-ein-report-einfuehrung.md","filePath":"einstieg/grundlagen/was-ist-ein-report-einfuehrung.md"}'),g={name:"einstieg/grundlagen/was-ist-ein-report-einfuehrung.md"};function p(o,e,d,h,m,c){return r(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="reports-und-ihre-einsatzmoglichkeiten-verstehen" tabindex="-1">Reports und ihre Einsatzmöglichkeiten verstehen <a class="header-anchor" href="#reports-und-ihre-einsatzmoglichkeiten-verstehen" aria-label="Permalink to &quot;Reports und ihre Einsatzmöglichkeiten verstehen&quot;">​</a></h1><p>Ein Report bereitet Daten aus der Schulverwaltung für eine bestimmte Ausgabe auf. Die Beispiele zeigen den Einsatz für Listen, Bescheinigungen und Zeugnisse.</p><p><a href="/bilder/grundlagen/einfuehrung-reports-beispiel-klassenliste.png"><img src="'+s+'" alt="Eine Klassenliste." loading="lazy"></a></p><p><em>Eine Klassenliste.</em></p><p><a href="/bilder/grundlagen/einfuehrung-reports-beispiel-lehrerliste.png"><img src="'+a+'" alt="Eine Lehrerliste." loading="lazy"></a></p><p><em>Eine Lehrerliste.</em></p><p><a href="/bilder/grundlagen/einfuehrung-reports-beispiel-stammblatt.png"><img src="'+l+'" alt="Ein Schülerstammblatt." loading="lazy"></a></p><p><em>Ein Schülerstammblatt.</em></p><p><a href="/bilder/grundlagen/einfuehrung-report-zeugnisse.png"><img src="'+u+'" alt="Ein Zeugnis." loading="lazy"></a></p><p><em>Ein Zeugnis.</em></p><p>SchILD-NRW verwaltet unter anderem Angaben zu Schülerinnen und Schülern, Lehrkräften und Ihrer Schule.</p><p>Sie können diese Daten exportieren, um sie beispielsweise in einem Tabellenkalkulationsprogramm weiterzuverarbeiten.</p><p>Mit dem <strong>Reportbaukasten</strong> gestalten Sie die Ausgabe direkt aus der Datenbank. Eine <strong>Reportvorlage</strong>, kurz <strong>Report</strong>, legt fest, welche Daten ausgegeben werden und wie das Dokument aussieht.</p><p>Bei einem Report kann es sich um eine Klassen- oder Kursliste mit Daten wie den Telefonnummern, Geburtsdatum oder Leistungsdaten zu den Schülern handeln.</p><p>Aber auch Stammblätter und Schulbescheinigungen und Zeugnisse werden in SchILD-NRW als Report angelegt und dann ausgegeben.</p><p>Fertige Reports können Sie über die Webseite des <a href="https://www.svws.nrw.de" target="_blank" rel="noreferrer">MSB für Schulverwaltungssoftware beziehen.</a></p><p>In dieser Dokumentation finden sich ausführliche Tutorials zur Verwendung, Veränderung und Erstellung von Reports.</p><p>Die Abbildungen auf dieser Seite zeigen Beispiele für die unterschiedlichen Ausgaben des Reportbaukastens.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Was_ist_ein_Report%3F_(Einf%C3%BChrung)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 4665.</p>',20)])])}const _=n(g,[["render",p]]);export{f as __pageData,_ as default};
